<div class="table-wrap"><table><thead><tr><th>Order / customer</th><th>Date</th><th>State</th><th>Total</th><th>Update</th><th>Tracking</th></tr></thead><tbody><?php foreach(($data['admin_orders']??$data['recent_orders']??[]) as $o): ?><tr><td><strong><?= e($o['order_number']) ?></strong><br><?= e($o['customer_name']??'') ?><br><span class="muted"><?= e($o['customer_email']??'') ?></span></td><td><?= e(date('d M Y H:i',strtotime($o['placed_at']))) ?></td><td><span class="status-pill"><?= e($o['status']) ?></span><br><span class="muted"><?= e($o['payment_status']) ?></span></td><td><?= e(format_price((float)$o['grand_total'],$o['currency'])) ?></td><td><form class="inline-form" action="/admin/orders/<?= e($o['id']) ?>/status" method="post"><?= csrf_field() ?><input type="hidden" name="return_to" value="<?= $data['admin_page']==='dashboard'?'/admin':'/admin/orders' ?>"><select name="status" aria-label="New order status"><?php foreach(['confirmed','processing','packed','shipped','delivered','cancelled'] as $s): ?><option value="<?= e($s) ?>" <?= $s===$o['status']?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select><input name="note" maxlength="500" placeholder="Optional status note"><button class="text-link">Save</button></form></td><td><form class="tracking-form" action="/admin/orders/<?= e($o['id']) ?>/shipment" method="post"><?= csrf_field() ?><input type="hidden" name="return_to" value="<?= $data['admin_page']==='dashboard'?'/admin':'/admin/orders' ?>"><input name="carrier" maxlength="120" placeholder="Courier"><input name="tracking_number" maxlength="120" placeholder="Tracking number"><input type="url" name="tracking_url" placeholder="HTTPS tracking URL"><button class="text-link">Save tracking</button></form></td></tr><?php endforeach; ?></tbody></table></div>
